-- 0097_template_home_products.sql (storefront templates, 2026-10-23)
--
-- Every template's home page must have at least one product grid (checked by
-- "every code template's home page" in
-- packages/store-sections/src/templates/library-templates.test.tsx). Two of
-- the 111 did not: Sage (botanica) and Zaki. Each gets the library
-- `products-grid` design on its home page, as a new template version built
-- from packages/store-sections/src/templates/{botanica,zaki}/ with
-- `templateConfigJson`. Stores that already applied either template are not
-- touched; the new version is what the gallery applies from now on.
--
-- Idempotent: once applied the current version is no longer the old one, so
-- the guards match nothing.

-- Sage (botanica) v2 → v3: best sellers grid on the home page.
-- Guarded: only when the template has no admin draft, its current version is
-- still the seeded v2 and no later version exists (an admin publish is
-- max(version) + 1), so a template an admin has touched is left alone.
WITH target AS (
  SELECT t.id
  FROM templates t
  JOIN template_versions cur ON cur.id = t.current_version_id
  WHERE t.key = 'botanica' AND t.deleted_at IS NULL AND t.draft_config IS NULL AND cur.version = 2
    AND NOT EXISTS (SELECT 1 FROM template_versions v WHERE v.template_id = t.id AND v.version > 2)
), new_version AS (
  INSERT INTO template_versions (template_id, version, schema_version, config, changelog)
  SELECT target.id, 3, 1,
