    'Sage v3: best sellers grid on the home page'
  FROM target
  ON CONFLICT (template_id, version) DO NOTHING
  RETURNING id, template_id
)
UPDATE templates t SET current_version_id = nv.id, updated_at = now()
FROM new_version nv
WHERE t.id = nv.template_id;

-- Rollback: make version 2 current again, then remove version 3:
--   UPDATE templates t SET current_version_id = v.id FROM template_versions v
--   WHERE t.key = 'botanica' AND v.template_id = t.id AND v.version = 2;
--   DELETE FROM template_versions v USING templates t
--   WHERE t.key = 'botanica' AND v.template_id = t.id AND v.version = 3;

-- Zaki (zaki) v1 → v2: devices grid on the home page.
-- Guarded: only when the template has no admin draft, its current version is
-- still the seeded v1 and no later version exists (an admin publish is
-- max(version) + 1), so a template an admin has touched is left alone.
WITH target AS (
  SELECT t.id
  FROM templates t
  JOIN template_versions cur ON cur.id = t.current_version_id
  WHERE t.key = 'zaki' AND t.deleted_at IS NULL AND t.draft_config IS NULL AND cur.version = 1
    AND NOT EXISTS (SELECT 1 FROM template_versions v WHERE v.template_id = t.id AND v.version > 1)
), new_version AS (
  INSERT INTO template_versions (template_id, version, schema_version, config, changelog)
  SELECT target.id, 2, 1,
