 جبس، وبنخبّي السلك.","translations":{"en":{"text":"Yes, brick, concrete or plasterboard, and we hide the cable."}}},"children":[]}]},{"id":"zaki-faq-home-n17","type":"accordionItem","props":{"title":"بتدفع إمتى؟","translations":{"en":{"title":"When do I pay?"}}},"children":[{"id":"zaki-faq-home-n18","type":"paragraph","props":{"text":"بعد ما الفني يخلص وتتأكد إن كل حاجة شغالة، كاش أو كارت أو إنستاباي.","translations":{"en":{"text":"After the technician finishes and you check everything works: cash, card or InstaPay."}}},"children":[]}]},{"id":"zaki-faq-home-n19","type":"accordionItem","props":{"title":"ما سياسة الاسترجاع؟","translations":{"en":{"title":"What is your return policy?"}}},"children":[{"id":"zaki-faq-home-n20","type":"paragraph","props":{"text":"يمكنك إرجاع أي منتج غير مستخدم خلال ١٤ يومًا في علبته الأصلية.","translations":{"en":{"text":"Return any unused item within 14 days in its original box."}}},"children":[]}]}]}],"style":{"background":"background","paddingTop":12,"paddingBottom":12,"paddingStart":24,"paddingEnd":24},"breakpointStyles":{"mobile":{"paddingStart":16,"paddingEnd":16}}}],"style":{"columns":2,"gap":1,"background":"border","borderWidth":1,"borderColor":"border","radius":14,"overflow":"hidden"},"breakpointStyles":{"mobile":{"columns":1}}}]}],"style":{"paddingTop":64,"paddingBottom":64},"breakpointStyles":{"mobile":{"paddingTop":40,"paddingBottom":40}}}],"source":"zaki-faq-home@1"}]}},{"slug":"about","isHome":false,"name":"عن بيت زكي","showInNav":true,"seo":{"title":"عن بيت زكي"},"content":{"sections":[{"id":"zaki-about-header","sectionId":"custom-section","version":1,"props":{},"componentTree":[{"id":"zaki-about-header-n1","type":"section","props":{"label":"عنوان الصفحة","translations":{"en":{"label":"Page header"}}},"children":[{"id":"zaki-about-header-n2","type":"container","props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"children":[{"id":"zaki-about-header-n3","type":"vFlex","props":{"label":"المحتوى","translati